INSERT INTO `products` (`id`, `category_id`, `brand_id`, `sku`, `slug`, `name`, `product_type`, `short_description`, `description`, `base_price`, `sale_price`, `warranty_months`, `requires_serial`, `stock_quantity`, `status`, `is_featured`, `created_at`, `updated_at`) VALUES
(236, 64, 67, 'LAP-ACER-ACER-PREDATOR-HELIOS-NEO-16-PHN16-71', 'at-2026-acer-predator-helios-neo-16-phn16-71', 'Acer Predator Helios Neo 16 PHN16 71', 'laptop', 'Acer Predator Helios Neo 16 PHN16 71 là mẫu laptop phù hợp cho học tập, làm việc và giải trí, có cấu hình cân bằng cùng chính sách bảo hành rõ ràng tại AeroTech.', 'Acer Predator Helios Neo 16 PHN16 71 phù hợp cho người dùng cần một thiết bị ổn định để học tập, làm việc, giải trí hoặc sáng tạo nội dung. Sản phẩm có thông tin cấu hình rõ ràng, dễ so sánh với các lựa chọn cùng phân khúc và được AeroTech hỗ trợ tư vấn trước khi mua.', '24990000.00', '23740500.00', 24, 1, 0, 'active', 1, '2026-06-01 02:07:02', '2026-06-04 03:41:13'),
