(466, 93, 84, 'SVC-BUILD-PC-CUSTOM', 'at-2026-dich-vu-tu-van-va-build-pc-theo-yeu-cau', 'Dịch vụ tư vấn và build PC theo yêu cầu', 'service', 'Dịch vụ tư vấn và build PC theo yêu cầu là dịch vụ kỹ thuật của AeroTech, phù hợp cho khách hàng cần tư vấn, lắp đặt, nâng cấp hoặc kiểm tra thiết bị.', 'Dịch vụ tư vấn và build PC theo yêu cầu hỗ trợ khách hàng xử lý nhu cầu kỹ thuật trước và sau khi mua hàng. Đội ngũ AeroTech tư vấn theo tình trạng thiết bị thực tế, nhu cầu sử dụng và ngân sách của khách hàng.', '300000.00', NULL, 0, 0, 0, 'active', 1, '2026-06-01 02:07:02', '2026-06-04 03:41:14'),
