(468, 93, 84, 'SVC-INSTALL-WINDOWS-SOFTWARE', 'at-2026-dich-vu-cai-at-windows-va-phan-mem', 'Dịch vụ cài đặt Windows và phần mềm', 'service', 'Dịch vụ cài đặt Windows và phần mềm là dịch vụ kỹ thuật của AeroTech, phù hợp cho khách hàng cần tư vấn, lắp đặt, nâng cấp hoặc kiểm tra thiết bị.', 'Dịch vụ cài đặt Windows và phần mềm hỗ trợ khách hàng xử lý nhu cầu kỹ thuật trước và sau khi mua hàng. Đội ngũ AeroTech tư vấn theo tình trạng thiết bị thực tế, nhu cầu sử dụng và ngân sách của khách hàng.', '200000.00', NULL, 0, 0, 0, 'active', 1, '2026-06-01 02:07:02', '2026-06-04 03:41:14'),
(469, 93, 84, 'SVC-UPGRADE-RAM-SSD', 'at-2026-dich-vu-nang-cap-ram-ssd', 'Dịch vụ nâng cấp RAM SSD', 'service', 'Dịch vụ nâng cấp RAM SSD là dịch vụ kỹ thuật của AeroTech, phù hợp cho khách hàng cần tư vấn, lắp đặt, nâng cấp hoặc kiểm tra thiết bị.', 'Dịch vụ nâng cấp RAM SSD hỗ trợ khách hàng xử lý nhu cầu kỹ thuật trước và sau khi mua hàng. Đội ngũ AeroTech tư vấn theo tình trạng thiết bị thực tế, nhu cầu sử dụng và ngân sách của khách hàng.', '150000.00', NULL, 0, 0, 0, 'active', 1, '2026-06-01 02:07:02', '2026-06-04 03:41:14'),
(470, 93, 84, 'SVC-CABLE-MANAGEMENT-SETUP', 'at-2026-dich-vu-i-day-va-toi-uu-goc-setup', 'Dịch vụ đi dây và tối ưu góc setup', 'service', 'Dịch vụ đi dây và tối ưu góc setup là dịch vụ kỹ thuật của AeroTech, phù hợp cho khách hàng cần tư vấn, lắp đặt, nâng cấp hoặc kiểm tra thiết bị.', 'Dịch vụ đi dây và tối ưu góc setup hỗ trợ khách hàng xử lý nhu cầu kỹ thuật trước và sau khi mua hàng. Đội ngũ AeroTech tư vấn theo tình trạng thiết bị thực tế, nhu cầu sử dụng và ngân sách của khách hàng.', '350000.00', NULL, 0, 0, 0, 'active', 1, '2026-06-01 02:07:02', '2026-06-04 03:41:14');
